def split_bill(prices, item, people):
    try:
        share = prices[item] / people
    except KeyError:
        return 'unknown item'
    except ZeroDivisionError:
        return 'nobody to pay'
    except Exception:
        return 'something went wrong'
    return 'each pays ' + str(share)
